const fields = ['name','summary','tasks','where','skills','study','reward','challenge','tryIt'];
const profiles = {};
for (const line of rows.trim().split(/\r?\n/).filter(line => line.trim())) {
 const values = line.split('|');
 if(values.length !== fields.length) throw new Error('Ficha incompleta: '+values[0]);
 const entry = Object.fromEntries(fields.map((field,index)=>[field,values[index].trim()]));
 if(profiles[entry.name]) throw new Error('Ficha duplicada: '+entry.name);
 entry.tasks = entry.tasks.split(';');
 profiles[entry.name] = entry;
}
